import{_ as p,c as e,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"晉","description":"高島易斷 - 晉","frontmatter":{"title":"晉","description":"高島易斷 - 晉"},"headers":[],"relativePath":"classics/takashima/035.md","filePath":"classics/takashima/035.md"}'),i={name:"classics/takashima/035.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="晉" tabindex="-1">晉 <a class="header-anchor" href="#晉" aria-label="Permalink to “晉”">​</a></h1><h2 id="晉-1" tabindex="-1">晉 <a class="header-anchor" href="#晉-1" aria-label="Permalink to “晉”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>晉：康侯用錫馬蕃庶，晝日三接。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>卦象上明下順，《離》明為日，故象君，《坤》順為臣，故象臣，合之為君明臣良之象。《坤》為國，為邦，故謂“侯”。《坤》為康，康安也；《坤》為馬，故謂“馬”；《坤》為眾，故謂“蕃庶”；《離》為日，故謂“晝”。蓋爻稱“康侯”者，謂明臣也，明臣升進，天子美之，賜以車馬蕃庶，言車馬之多也。“晝日三接”者，言不特賜予之多，且覿見之頻，一晝之間，三度接見也。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>明出地上，《晉》，君子以自昭明德。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>日西入為夕，東出為旦。方其始出，漸進漸高，愈高愈明，光無不照，幽隱遍燭，即《晉》之象。君子法此象，以自明其德。德，心之德也，與生俱來，靈明夙具，本無一毫私慾，得而蔽掩，猶日之初出於地，滄滄涼涼，明光華照，本無一些雲翳。“自昭明德”，昭，即明也，所謂自昭明德，明德而猶待於明。此事不容假貸，唯在自知之而自明之耳。君子切而責之於自，致知格物，以啟自昭之端，誠意正心，以致自昭之實，謂之“君子以自昭明德”也。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：正當好運新來，猶朝日初出，漸升漸高，明光普照也。吉。</p><p>○　問戰徵：當大軍初發，順道而進，宜日戰，不宜夜攻。</p><p>○　問營商：最利煤炭地火等生業，取其明也。吉。</p><p>○　問功名：有功名指日高升之象，吉。</p><p>○　問訟事：宜返而自訟。</p><p>○　問家宅：此宅朝東南，高敞明朗，得太陽吉曜照臨，大吉。</p><p>○　問六甲：生女。</p><p>○　問失物：在明堂中尋之，得。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>初居下卦之始，柔進上行，自初起，首曰“晉如”，若欲進而未果；繼曰“摧如”，若有摧而見阻。初與四應，四不當位，不特不應，且所以摧初之進者，實四為之也。然雖見摧，惟其得貞，是以吉也。“罔孚”者，推其摧之由來，雖四為之，亦由上下之交未孚耳。《坤》為裕，故曰“裕”。當其未孚，或汲汲以幹進，或悻悻而懷忿，皆所以取咎也，唯雍容寬裕，樂道自處，咎何有焉？故曰“裕無咎”。《象傳》曰“獨行正也”，謂摧者不正，《晉》者能獨行其正耳。“無咎，未受命也”，謂其未受賜命，只宜寬裕以待之耳。</p><h2 id="初六佔" tabindex="-1">初六佔 <a class="header-anchor" href="#初六佔" aria-label="Permalink to “初六佔”">​</a></h2><p>○　問時運：目下好運初來，雖無災咎，尚未盛行，宜遲緩以待之。吉。</p><p>○　問戰徵：初次行軍，眾心未定，宜寬以待之。吉。</p><p>○　問營商：貨物初到，商情未洽，宜寬以時日，早則四日，遲則四月，到四爻曰“眾允”，則貨可旺銷，必大獲利。</p><p>○　問功名：功名固所自有，不可知者遲早耳，宜寬懷以俟。</p><p>○　問家宅：此宅本吉，一時未許進居，為兩情未洽，緩則必成。</p><p>○　問婚姻：因探聽未確，遲緩可成。</p><p>○　問失物：日後可得。</p><p>○　問疾病：宜寬緩調養，可愈．</p><p>○　問六甲：生女。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>某縣人來，請佔志願成否，筮得《晉》之《噬嗑》。</p><p>斷曰：《晉》者進也，《晉》當初爻，是進步之初也，“摧如”者，欲進而有所摧折也，進者雖正，無如人不我信也。今足下佔問志願而得初爻，知足下品行端正，才具可用，但一時眾情未孚，是以欲進又阻。初與四應，四不應初，反來阻初，料足下所託謀事之人，此人不能相助，反致相毀，故一時難望遂願。宜到四爻曰“眾允”之日，志願可遂。一爻一月，大約在四月以後，大吉。其人嘗攜建議書，請謁某貴顯，不能面達，反受警部之辱，得此佔所云，大有感悟。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>“愁如”，不悅之意，與“摧如”不同，愁者在我，摧者為人所阻。然二之所以“愁如”，實因初之見摧而來也。居中履正，故“貞吉”。“介福”，謂大福。“王母”，以二與五相應，五王位，《坤》陰，《坤》為妣，故曰“王母”；“王母”，即所謂太后也。二屬《坤》，《坤》通《乾》，《乾》為“介福”。按《井》三曰王明受福，《既濟》五曰“實受其福”，《井》三、《既濟》五，皆得《乾》體，其福蓋皆受之於《乾》也。二又互《艮》，《艮》為手，手持福以與二，二受之，故曰“受茲介福”。九家《易》雲：“介福謂馬與蕃庶之物也。”《象傳》曰“以中正也”，謂其守此中正，不以無應而回其志，故終得受此大福也。</p><h2 id="六二佔" tabindex="-1">六二佔 <a class="header-anchor" href="#六二佔" aria-label="Permalink to “六二佔”">​</a></h2><p>○　問時運：目下運非不佳，但所求多阻，中心未免憂結，能守正不改，終必亨通大利。</p><p>○　問戰徵：前番進攻，既遭摧折，今此再進，殊切愁懼，然能臨事而懼，後必獲吉。六二與六五相應，六五辰在卯，上值氐、房、心、尾，氐星前二大星主后妃，故取象王母，禱之，則有福。</p><p>○　問營商：因前販之貨，已被折耗，今茲未免懷愁，故曰“晉如愁如”。惟中正自守，至五爻乃曰“失得勿恤，往吉，無不利”，蓋勸其不必憂愁，而自然獲福也。</p><p>○　問功名：今雖憂愁，至五爻曰“往有慶”，蓋二年之後，即可獲吉。</p><p>○　問婚姻：吉，但目下不就，須待第三年可成。當有祖母為之作主。</p><p>○　問家宅：當遷居，與祖母同居共食，吉。</p><p>○　問失物：久後可得。</p><p>○　問六甲：生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>明治五年，餘隨陸軍大佐福原實氏，赴贊州謀築兵營。時坐輪船中，福原氏曰：方今我國形勢，前途未可知，請試一佔。筮得《晉》之《未濟》。</p><p>斷曰：《晉》者進也，欲進而愁其見摧，是進而未能進也，故爻曰“晉如愁如”。六二以陰居陰，但得中正，與初為比，因初之摧，倍切憂思，可謂臨事知懼，故得“貞吉”。今佔我國時勢得此爻，我國自維新以來，力圖進取，以啟文明，初時內為舊藩士意見不合所阻，外為泰西各國風教不同所困，下又為改革不便所擾，是以欲進而未能遽進。茲當二爻，二與五應，五屬尊位，知當道大臣，蒙我皇上帝心簡在，上下一心，固不敢畏難思退，惟是進步艱難，日切憂慮，此即爻辭之所謂“晉如愁如”是也。當日三條公以下諸位大臣，秉正謀國，不特受知於皇上，且為太后所信任也，此即爻辭所謂“受茲介福，於其王母”是也。就前後爻辭而詳推之，初爻則屬之前事，二爻則屬之今日，二五相應，是即《彖》所稱“康侯”者也。三爻則初之“罔孚”者，而眾孚矣，得以上行無悔。四爻則恐有讒邪在位，如鼠之晝伏夜行，進退詭秘，意將竊弄政權，為宜戒也。五爻當君位，是明君在上，殷殷焉為諸臣勸駕。曰“失得勿恤，往吉，無不利”，蓋指二之“愁如”者言，謂失得不足憂，往則“無不利”。“有慶”者，即受福之謂也。上爻居《離》之極，《離》上“王用出徵”，故五爻亦用“伐邑”，謂再有摧我者，當以王師討之，使不敢復阻我前進也。爻象一爻或當一年，或當十年，可以定數求之。統之《晉》者進也，繼《大壯》而來，為宜柔順上行，不宜剛健躁進，蓋取《坤》之順而在下，尤必取《離》之明而在上，君子自昭明德，胥是道也。武功必先文德，上爻之“伐邑”，知亦不得已而用之耳。我國明良交際，文武兼修，國富兵強，日進日盛，正萬年有道之休也，豈不休哉！福原氏聞之，大為感服。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>三居內卦之上，與四為比，剛阻於前，似宜有悔。“允”，信也，六三辰在亥，得《乾》，《乾》為信。三比近初二，又與初二同心並力，合之為三，三人成眾，故“眾允”。外卦為《離》，《離》取其明，所謂克明克允是也。“眾允”則四不能摧，故“悔亡”。古今來為國謀事，要皆以眾心之向背為成敗者也，眾心不順，其事雖正，卒無成功。孟子所謂“多助之至，天下順之”者，“眾允”之義也。初之“罔孚”，未信也；三之“眾允”，見信也。孔子所謂“信而後諫”，“信而後勞其民”，事上使下，道在是焉。《象傳》曰“眾允之，志上行也”，三與上應，志在上行，故能與眾同信也。</p><h2 id="六三佔" tabindex="-1">六三佔 <a class="header-anchor" href="#六三佔" aria-label="Permalink to “六三佔”">​</a></h2><p>○　問時運：目下災悔已去，大眾悅服，故吉。</p><p>○　問營商：初時為眾所摧，不能獲利，今眾情和睦，可以無咎，賣買皆利。</p><p>○　問戰徵：眾志成城，戰必勝，攻必克，上行無悔。</p><p>○　問功名：得眾人推舉乃成。</p><p>○　問家宅：主眷屬和睦，吉。</p><p>○　問婚姻：兩姓和諧，吉。</p><p>○　問訟事：得有第三人出而處理，兩造允從，無悔。</p><p>○　問六甲：生女。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>九州商人某來，請佔購買某大會社物品成否，如何，筮得《晉》之《旅》。</p><p>斷曰：卦體下順上明，顯見以明白無欺，柔順得眾為要。今佔購賣物品，而得《晉》三爻，知其在初爻，己欲購賣，為人所摧折不成；二爻又欲賣之，為己多愁慮未定。茲當三爻，已見眾心允洽，雖四爻為貪人，意欲從中取利，然因大眾已允，亦不復阻止矣。準可購買，無悔。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>四爻以陽居陰，不中不正，當上下四陰之中，上互《坎》，下互《艮》，《坎》為隱伏，《艮》為鼠，《坎》隱而傷明，《艮》止而傷順，無其德而居其位，上承陰柔之主，竊弄威權，下抑眾陰，使忠言不得上達，以隔絕上下之效者也。其貪戾之性，猶如鼫鼠，故曰“晉如鼫鼠”。自來奸臣得位，其性貪殘，晝伏夜動，詭秘百端，竊威弄權，狡同鼫鼠，一旦明德當陽，察識奸邪，渾如碩鼫見貓，罔不捕滅，故曰“貞厲”。《象傳》曰“不當位也”，謂斯不當居斯位，為竊位也。按；《解》之卦，以陰居陽象狐，《晉》之卦，以陽居陰象鼠，此卦互體《艮》，一陽在上，故稱“鼫鼠”。狐性疑，在《解》當去其疑；鼠性貪，在《晉》當去其貪，取象各有所當。</p><h2 id="九四佔" tabindex="-1">九四佔 <a class="header-anchor" href="#九四佔" aria-label="Permalink to “九四佔”">​</a></h2><p>○　問時運：運有蹊蹺，宜光明正大處之，若持首鼠兩端之見，好為狡詐，必兇。</p><p>○　問戰徵：《晉·彖》曰“晝日三接”，或曰接即捷，言一晝間而得三捷。若疑而又貪，如鼠之晝伏夜動，則危。</p><p>○　問功名：爻曰“鼫鼠”，鼫鼠謂五技皆劣，是必不能得志也。</p><p>○　問營商：鼠性貪，貪無不敗，防為同夥貪財致敗。</p><p>○　問家宅：鼠為穴蟲，善盜，宅多鼠，必主耗失。不利。</p><p>○　問疾病：《詩》雲“鼠思泣血”，或有嘔血之症；又曰“鼠憂以癢”，或有疥瘡之疾，是亦可危。</p><p>○　問訟事：首鼠兩端，是一卻一前，一時不能決也。</p><p>○　問行人：晝伏夜行，必有事故，一時不歸。</p><p>○　問失物：已入鼠穴，不得。</p><p>○　問婚姻：“鼠”為鼠竊，婚姻不正。</p><p>○　問六甲：生女。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>商人某來，請佔家政，筮得《晉》之《剝》。</p><p>斷曰：卦體順麗大明，柔進上行，足見主家者公明在上，一門柔順和樂，有家業日進之象。今佔得四爻，以陽居陰，位不得正；鼠為穴蟲，晝伏夜動，貪而畏人，陰物也，四爻如之，故爻辭曰“晉如鼫鼠”。料足下家中必有鼠竊之徒，管理家務。如《詩》所詠“碩鼠碩鼠”，一則曰食苗，再則曰食谷，知盜食家產，為禍非淺，故曰“貞厲”，言家道雖貞亦厲也。足下其審之慎之！</p><p>子爵五條為榮君，將遷居西京，請佔其吉凶如何？筮得《晉》之《剝》。</p><p>斷曰：此卦內《坤》外《離》，為《晉》，《象》曰“明出地上”。出於東為明，日入於西為晦，卦德在明，是宜東不宜西也。今君將移居西京，辭爵歸隱，佔得《晉》四爻，按《晉》者為進，不宜於退，日出在東，不宜就西，象皆不合。四爻辭曰“《晉》如鼯鼠，貞厲”，謂首鼠兩端，一前一卻，正如君之進退疑慮，欲遷未決。“貞厲”者，謂退隱意非不正，恐後有危厲也。勸君不必遷移。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>五爻為《晉》之主，高居尊位，柔而得中，惟與四相比暱，四遂得竊弄威權，隔絕二三，不得親近，是以有悔。然五躬備明德，智足察奸，黜六四而任六二，昭明有融，上下交孚，故曰“悔亡”。“失得勿恤”者，謂五不自恃其明，委用六二，信任勿疑，計是非，不計得失，即有小失小得，不足慶也。“往”即“上行”，指康侯往朝於天子也。“吉，無不利”，指受介福於王母也，故《象傳》曰“往有慶也。”慶，即“受茲介福”之謂也。</p><h2 id="六五佔" tabindex="-1">六五佔 <a class="header-anchor" href="#六五佔" aria-label="Permalink to “六五佔”">​</a></h2><p>○　問時運：目下正當盛運，災去福來，有得無失，大吉。</p><p>○　問戰徵：轉敗為勝，在此一戰，奮勇前往，立見成功。</p><p>○　問營商：前此小失，今可大得，吉。</p><p>○　問功名：不必汲汲求名，可無意得之也。吉。</p><p>○　問家宅：日出於東，《離》位南方，此宅必朝東南。從前小有災悔，今則屋運已轉，吉無不利。</p><p>○　問婚姻：以九五為男家，六二為女家，兩爻皆吉，大利。</p><p>○　問訟事：曰“悔亡”，謂災害已去，罷訟則吉。</p><p>○　問失物：往尋必得。</p><p>○　問六甲：生女。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>華族某來，請佔氣運，筮得《晉》之《否》。</p><p>斷曰：《晉》五爻為一卦之主，高明在上，且《坤》為邦為國，有屏藩一國之象。閣下佔氣運而得此爻，爻辭曰“悔亡，失得勿恤”，想閣下自廢藩以來，從前或小有災悔，今能柔順上進，觀光志正，是不以失得為憂也，故曰“悔亡”。“往”者，往朝也，上下交孚，故無往而不利也。聞閣下欲以每歲財產餘利，教育藩士子弟，以為國家培植人材，至財產之得失，不復計慮，《彖》所稱康侯者，必在閣下矣。他日恩賞下逮，車馬藩庶，行有待焉，《象傳》所謂“往有慶”者，此也。</p><p>明治三十一年，佔內閣氣運，筮得《晉》之《否》。</p><p>斷曰：此卦明出地上，順而麗夫大明，國家治體，駸駸上進之氣運也。今佔得五爻，五居君位，昭明有融，上下交孚，君明臣良，正在此時，然其間黜陟，不無些少紛擾。在內閣諸公，皆正色立朝，秉忠從事，不計勞辱，謂之“悔亡，失得勿恤，往吉，無不利也”。果哉！是年伊藤侯辭總理之爵，大隈板垣二伯入內閣，五月，山縣侯升為總理。此間雖非無紛擾，國家益見進步，正合此佔。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>“角”者，陽而在上，喻威猛之義。上爻處《晉》之極，過剛失中，故曰“晉其角”，謂其知進不知退也。《離》為甲，為戎，《離》上“王用出徵”，上爻體《離》，故亦曰“維用伐邑”。用者五，邑指四，奉命而伐之者，上也。四既有罪，聲罪致討，兵雖危事，吉而無咎也。然幹羽可以格頑，玉帛可以戢爭，不用文德，而用武功，亦未始非聖明之累也，故雖正亦吝，而《傳》曰“道未光也”。</p><h2 id="上九佔" tabindex="-1">上九佔 <a class="header-anchor" href="#上九佔" aria-label="Permalink to “上九佔”">​</a></h2><p>○　問時運：目下好運將終，防有事故，然無大害。</p><p>○　問戰徵：只可近徵國內，不可遠伐海外。危而終吉。</p><p>○　問營商：於同業防有紛爭，於事則危，於貨則利，於情則吝，幸無咎也。</p><p>○　問功名：“晉，進也”，角在首上，有首選之象。功名成後，防有從戎之役。吉。</p><p>○　問家宅：居者於鄉黨中，有紛爭之事，未免不安，然無大咎。</p><p>○　問婚姻：上與三相應，上與三，即為男女兩姓，始有紛擾，終得和諧，故“悔亡”，與三同也。</p><p>○　問訟事：《雀角》之詩，刺訟也。罷訟則吉。</p><p>○　問六甲：生女。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>友人某來曰：今有一會社，自創立以來，餘所關慮。昨年總會，整頓社員，迄後事務不整，有株主之紛擾，其由社勢之不振乎？抑由社員之不力乎？請一佔其盛衰。筮得《晉》之《豫》。</p><p>斷曰：《晉》者，明出地上，有社運日進日新之象。今佔得上爻，為《晉》之極，是進無可進矣。物極必反，意者重有改革乎？“伐邑”者，即正其不正，可用前社員之練達者，以定會社之規則，庶幾可得吉矣。事雖危殆，終無咎焉，從此社業復興，不失其正。然自有識者觀之，不免為之竊笑也，故曰“貞吝”。</p>',112)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
